// ProductList.vue
<template>
  <div class="container mt-5">
    <div class="card shadow-sm border-0 bg-light">
      <div class="card-body">
        <h3 class="mb-4 text-brown fw-light"><i class="bi bi-box-seam me-2"></i>Product Inventory</h3>
        
        <!-- Search and filter bar -->
        <div class="bg-white p-3 rounded mb-4 shadow-sm">
          <div class="row align-items-center">
            <div class="col-md-6">
              <div class="input-group">
                <span class="input-group-text bg-brown text-white border-brown">
                  <i class="bi bi-search"></i>
                </span>
                <input type="text" class="form-control border-brown" placeholder="Search products...">
              </div>
            </div>
            <div class="col-md-6 text-md-end mt-3 mt-md-0">
              <span class="text-muted me-2">{{ products.length }} products</span>
            </div>
          </div>
        </div>

        <div v-if="paginated.length === 0" class="text-center py-5 text-muted">
          <i class="bi bi-inbox fs-1 d-block mb-3"></i>
          <p>No products found in inventory.</p>
        </div>
        
        <div v-for="product in paginated" :key="product.id" class="card mb-3 border-0 shadow-sm hover-card">
          <div class="card-body">
            <div class="row">
              <div class="col-md-3 col-lg-2 mb-3 mb-md-0">
                <div class="product-img-container bg-light rounded d-flex align-items-center justify-content-center p-2">
                  <img
                    v-if="product.image"
                    :src="fullImageUrl(product.image)"
                    alt="Product image"
                    class="product-img"
                  />
                  <i v-else class="bi bi-image text-muted" style="font-size: 2rem;"></i>
                </div>
              </div>
              <div class="col-md-9 col-lg-10">
                <h5 class="text-brown mb-2">{{ product.name }}</h5>
                <p class="text-muted mb-3 product-description">{{ product.description }}</p>
                <div class="d-flex justify-content-between align-items-center">
                  <div>
                    <span class="badge bg-brown me-2">₱{{ product.price }}</span>
                    <span class="badge bg-light text-dark border">Stock: {{ product.stock }}</span>
                  </div>
                  <div>
                    <button class="btn btn-sm btn-outline-brown me-2" @click="openEditModal(product)">
                      <i class="bi bi-pencil me-1"></i> Edit
                    </button>
                    <button class="btn btn-sm btn-outline-danger" @click="deleteProduct(product.id)">
                      <i class="bi bi-trash me-1"></i> Delete
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Pagination -->
        <nav v-if="totalPages > 1" aria-label="Product pagination">
          <ul class="pagination pagination-sm justify-content-center mt-4">
            <li class="page-item" :class="{ disabled: currentPage === 1 }">
              <a class="page-link text-brown border-brown" href="#" @click.prevent="currentPage--">
                <i class="bi bi-chevron-left"></i>
              </a>
            </li>
            <li
              v-for="n in totalPages"
              :key="n"
              class="page-item"
              :class="{ active: currentPage === n }"
            >
              <a class="page-link border-brown" :class="{'bg-brown text-white': currentPage === n, 'text-brown': currentPage !== n}" href="#" @click.prevent="currentPage = n">{{ n }}</a>
            </li>
            <li class="page-item" :class="{ disabled: currentPage === totalPages }">
              <a class="page-link text-brown border-brown" href="#" @click.prevent="currentPage++">
                <i class="bi bi-chevron-right"></i>
              </a>
            </li>
          </ul>
        </nav>
      </div>
    </div>

    <!-- Edit Modal -->
    <div class="modal fade" ref="editModal" id="editModal" tabindex="-1">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content border-0 shadow">
          <form @submit.prevent="submitEdit">
            <div class="modal-header bg-brown text-white">
              <h5 class="modal-title"><i class="bi bi-pencil-square me-2"></i>Edit Product</h5>
              <button type="button" class="btn-close btn-close-white" @click="closeEditModal"></button>
            </div>
            <div class="modal-body">
              <div class="mb-3">
                <label class="form-label text-brown">Product Name</label>
                <input v-model="editProduct.name" class="form-control border-brown" placeholder="Name" required />
              </div>
              <div class="mb-3">
                <label class="form-label text-brown">Description</label>
                <textarea v-model="editProduct.description" class="form-control border-brown" placeholder="Description" rows="3" required></textarea>
              </div>
              <div class="row mb-3">
                <div class="col-6">
                  <label class="form-label text-brown">Price (₱)</label>
                  <input type="number" v-model.number="editProduct.price" class="form-control border-brown" placeholder="Price" required />
                </div>
                <div class="col-6">
                  <label class="form-label text-brown">Stock</label>
                  <input type="number" v-model.number="editProduct.stock" class="form-control border-brown" placeholder="Stock" required />
                </div>
              </div>
              <div class="mb-3">
                <label class="form-label text-brown">Product Image</label>
                <input type="file" @change="handleEditImage" class="form-control border-brown" accept="image/*" />
              </div>
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-outline-secondary" @click="closeEditModal">Cancel</button>
              <button type="submit" class="btn btn-brown">
                <i class="bi bi-check-lg me-1"></i> Save Changes
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import axios from '../axios'
import * as bootstrap from 'bootstrap'

export default {
  data() {
    return {
      products: [],
      currentPage: 1,
      perPage: 5,
      editProduct: { id: null, name: '', description: '', price: 0, stock: 0 },
      editImage: null,
      modalInstance: null
    }
  },
  computed: {
    totalPages() {
      return Math.ceil(this.products.length / this.perPage)
    },
    paginated() {
      const start = (this.currentPage - 1) * this.perPage
      return this.products.slice(start, start + this.perPage)
    }
  },
  methods: {
    fullImageUrl(path) {
      if (path.startsWith('http')) return path
      return `http://127.0.0.1:8000${path.startsWith('/') ? path : '/media/' + path}`
    },
    async fetchProducts() {
      try {
        const res = await axios.get('products/')
        this.products = res.data
      } catch {
        this.showToast('❌ Failed to load products.', 'danger')
      }
    },
    async deleteProduct(id) {
      if (!confirm('Are you sure you want to delete this product?')) return
      
      try {
        await axios.delete(`products/${id}/`)
        this.showToast('🗑️ Product deleted successfully.', 'success')
        this.fetchProducts()
      } catch {
        this.showToast('❌ Cannot delete product.', 'danger')
      }
    },
    openEditModal(product) {
      this.editProduct = { ...product }
      this.editImage = null
      this.modalInstance = new bootstrap.Modal(this.$refs.editModal)
      this.modalInstance.show()
    },
    closeEditModal() {
      if (this.modalInstance) this.modalInstance.hide()
    },
    handleEditImage(e) {
      this.editImage = e.target.files[0]
    },
    async submitEdit() {
      const formData = new FormData()
      for (let key in this.editProduct) {
        if (key !== 'image') {
          formData.append(key, this.editProduct[key])
        }
      }
      if (this.editImage) {
        formData.append('image', this.editImage)
      }

      try {
        await axios.patch(`products/${this.editProduct.id}/`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        })
        this.showToast('✅ Product updated successfully!', 'success')
        this.fetchProducts()
        this.closeEditModal()
      } catch (err) {
        this.showToast('❌ Failed to update product.', 'danger')
      }
    },
    showToast(message, type) {
      // Use a simple alert for now, but you could implement a toast system
      alert(message)
    }
  },
  mounted() {
    const token = localStorage.getItem('access')
    const isStaff = localStorage.getItem('is_staff') === 'true'
    if (!token || !isStaff) {
      alert('⛔ Access denied. Staff only.')
      this.$router.push('/login')
      return
    }
    this.fetchProducts()
  }
}
</script>

<style scoped>
/* Brown theme colors */
:root {
  --brown-50: #efebe9;
  --brown-100: #d7ccc8;
  --brown-200: #bcaaa4;
  --brown-300: #a1887f;
  --brown-400: #8d6e63;
  --brown-500: #795548;
  --brown-600: #6d4c41;
  --brown-700: #5d4037;
  --brown-800: #4e342e;
  --brown-900: #3e2723;
}

.text-brown {
  color: var(--brown-600);
}

.bg-brown {
  background-color: var(--brown-600);
}

.border-brown {
  border-color: var(--brown-500) !important;
}

.btn-brown {
  background-color: var(--brown-600);
  border-color: var(--brown-600);
  color: white;
}

.btn-brown:hover {
  background-color: var(--brown-700);
  border-color: var(--brown-700);
  color: white;
}

.btn-outline-brown {
  border-color: var(--brown-500);
  color: var(--brown-600);
}

.btn-outline-brown:hover {
  background-color: var(--brown-600);
  border-color: var(--brown-600);
  color: white;
}

.product-img-container {
  height: 100px;
  width: 100%;
  overflow: hidden;
}

.product-img {
  max-height: 90px;
  max-width: 100%;
  object-fit: contain;
}

.product-description {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.hover-card {
  transition: all 0.2s ease;
}

.hover-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 .5rem 1rem rgba(0,0,0,.1) !important;
}

/* Add Bootstrap Icons */
@import url("https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css");
</style>
